-- programs_undergraduate_settings.sql
CREATE TABLE IF NOT EXISTS programs_undergraduate_settings (
  id INT PRIMARY KEY AUTO_INCREMENT,
  subhero_image_url VARCHAR(255) DEFAULT '/adamson-ccit/public/assets/images/programs/undergrad.jpg',
  subhero_lead TEXT,
  programs_grid MEDIUMTEXT,
  cta_title VARCHAR(255),
  cta_description TEXT,
  cta_action_url VARCHAR(255),
  cta_action_label VARCHAR(100),
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
);

